def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    value = (change / v1) * 100

    return {
        "value": value,
        "trace": {
            "base_value_2012": v1,
            "comparison_value_2013": v2,
            "absolute_change": change,
            "change_ratio": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
